<?php /** @var array $rows @var array $counts @var string $f @var string $q */ use MagicCMS\Plugins\Recruit\Recruit; ?>
<p><a class="btn btn-ghost" href="<?= e(url('admin/recruit/setup')) ?>">⚙ <?= e(t('Positions, questions & settings')) ?></a> <a class="btn btn-ghost" href="<?= e(url('recruit')) ?>"><?= e(t('Public form')) ?> →</a></p>
<div class="filter-tabs"><a class="<?= $f === '' ? 'is-on' : '' ?>" href="<?= e(url('admin/recruit')) ?>"><?= e(t('All')) ?> <small><?= (int) array_sum($counts) ?></small></a>
<?php foreach (Recruit::STATUSES as $k => $_): ?><a class="<?= $f === $k ? 'is-on' : '' ?>" href="<?= e(url('admin/recruit?f=' . $k)) ?>"><?= e(Recruit::label($k)) ?> <small><?= (int) ($counts[$k] ?? 0) ?></small></a><?php endforeach ?></div>
<form class="inline-form" method="get" action="<?= e(url('admin/recruit')) ?>"><input class="input" name="q" value="<?= e($q) ?>" placeholder="<?= e(t('Search name or e-mail')) ?>"><?php if ($f): ?><input type="hidden" name="f" value="<?= e($f) ?>"><?php endif ?><button class="btn btn-ghost"><?= e(t('Search')) ?></button></form>
<div class="card"><div class="card-body table-wrap"><table class="table"><thead><tr><th><?= e(t('Applicant')) ?></th><th><?= e(t('Position')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Sent')) ?></th></tr></thead><tbody>
<?php foreach ($rows as $a): ?><tr><td><a href="<?= e(url('admin/recruit/' . (int) $a['id'])) ?>"><strong><?= e($a['name']) ?></strong></a><br><small class="muted"><?= e($a['email']) ?></small></td><td><?= e($a['position_title'] ?: '—') ?></td><td><span class="badge rc-<?= e($a['status']) ?>"><?= e(Recruit::label($a['status'])) ?></span></td><td><?= e(time_ago($a['created_at'])) ?></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="4" class="muted"><?= e(t('No applications.')) ?></td></tr><?php endif ?></tbody></table></div></div>
